        az := sqrt((1 - sin(Pi/14))/(2 * (1 + 2 * sin(Pi/14)))); // 0.5186676235534391

//ѕоворот точки p вокруг нормированной оси v
        procedure RotatePoint(Xp, Yp, Zp, Xv, Yv, Zv, Angle); 
        begin 
          ca := Cos(Angle);
          sa := Sin(Angle);
          c2 := 1 - Cos(Angle);
         
          Nx := Xp * (Xv * c2 * Xv + ca) + 
                Yp * (Yv * c2 * Xv - sa * Zv) + 
                Zp * (Zv * c2 * Xv + sa * Yv);
         
          Ny := Xp * (Xv * c2 * Yv + sa * Zv) + 
                Yp * (Yv * c2 * Yv + ca) + 
                Zp * (Zv * c2 * Yv - sa * Xv);
         
          Nz := Xp * (Xv * c2 * Zv - sa * Yv) + 
                Yp * (Yv * c2 * Zv + sa * Xv) + 
                Zp * (Zv * c2 * Zv + ca);
        end;


        // 1/sqrt(1+az^2) = sqrt((2 + 4 sin(Pi/14))/(3 + 3 sin(Pi/14)))

//        ShowMessage(Nx); // 0
//        ShowMessage(Ny); //-0.999328575420621 * k
