        Nx := 0;
        Ny := -k * (sqrt(sin(Pi/14) + cos(Pi/7)) + 3 * sqrt((1 + 2 * sin(Pi/14))/(1 + sin(Pi/14))) * cos(Pi/14))/(3 * sqrt(2));
        Nz := k * (1 - 4 * sin(Pi/14)) / 3;

        sp := sin(Pi/14);
        Nx := 0;
        R2 := -k * 2/3 * sqrt(2 * (1 - sp) * (2 * sp + 1));
        H2 := k * (1 - 4 * sp) / 3;


        for i := 0 to 2 do begin
            x2[i] := R2 * sin(2*Pi/3 * i);
            y2[i] := R2 * cos(2*Pi/3 * i);
        end;



        R := H1 * az / sqrt(1 + az^2);
